describe('Protected Page Authentication Redirection', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should redirect unauthenticated user to login when accessing protected page', () => {
    // Clear all cookies and local storage to ensure unauthenticated state
    cy.clearCookies();
    cy.clearLocalStorage();

    // Attempt to navigate directly to a protected page
    cy.visit('/settings');

    // Verify that the user is redirected to the login page
    cy.url().should('include', '/login');

    // Verify that the login page is displayed
    cy.get('[data-testid="login-form"]').should('be.visible');

    // Verify that the login form contains necessary fields
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Verify that the login button is present
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Verify that the page title reflects the login page
    cy.get('[data-testid="page-title"]').should('contain', 'Login');
  });

  it('should not redirect authenticated user when accessing protected page', () => {
    // Authenticate the user by visiting login and submitting credentials
    cy.visit('/login');
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');
    cy.get('[data-testid="login-button"]').click();

    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest');

    // Verify successful login and redirection to dashboard
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Navigate to a protected page
    cy.visit('/settings');

    // Verify that the user is still on the settings page and not redirected to login
    cy.url().should('include', '/settings');
    cy.get('[data-testid="settings-page-title"]').should('be.visible');

    // Verify that protected page content is visible
    cy.get('[data-testid="user-profile-section"]').should('be.visible');
    cy.get('[data-testid="account-settings-form"]').should('be.visible');

    // Verify that the user is not prompted to log in
    cy.get('[data-testid="login-form"]').should('not.exist');
  });
});
